'use strict';
const $ = (s, r = document) => r.querySelector(s);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths = {
 home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',
 grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',
 radar:'M21 12a9 9 0 1 1-9-9 M17 12a5 5 0 1 1-5-5 M12 12l8-8 M17 3h4v4',
 briefcase:'M8 6V4h8v2 M3 7h18v13H3z M3 12c6 4 12 4 18 0 M12 12v4',
 file:'M14 2H5v20h14V7z M14 2v6h5 M8 12h8 M8 16h6',
 building:'M4 21V3h12v18 M16 10h4v11 M2 21h20 M8 7h1 M12 7h1 M8 11h1 M12 11h1 M8 15h1 M12 15h1 M8 21v-3h4v3',
 user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M4 21v-2a8 8 0 0 1 16 0v2',
 chart:'M4 3v17h17 M8 15l4-5 4 2 5-7',
 settings:'m9 3 1-2h4l1 2 2 1 2-1 2 4-2 2v3l2 2-2 4-2-1-2 1-1 3h-4l-1-3-2-1-2 1-2-4 2-2V9L3 7l2-4 2 1Z M15 11a3 3 0 1 1-6 0 3 3 0 0 1 6 0',
 search:'M16 10a6 6 0 1 1-12 0 6 6 0 0 1 12 0 M15 15l6 6',
 plus:'M12 5v14 M5 12h14', arrow:'M5 12h14 M14 7l5 5-5 5', external:'M14 3h7v7 M21 3 10 14 M10 3H3v18h18v-7',
 chevron:'m9 5 7 7-7 7', left:'m15 5-7 7 7 7', check:'m5 12 4 4L19 6', close:'m6 6 12 12 M6 18 18 6',
 bookmark:'M6 3h12v19l-6-4-6 4Z', pin:'M18 9c0 5-6 12-6 12S6 14 6 9a6 6 0 1 1 12 0 M14 9a2 2 0 1 1-4 0 2 2 0 0 1 4 0',
 spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z',download:'M12 3v12 m-5-5 5 5 5-5 M4 15v6h16v-6',
 clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M12 7v5l3 2', info:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M12 11v6 M12 7h.01',
 mail:'M3 5h18v14H3z m0 0 9 8 9-8',shield:'M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6Z m-5 10 3 3 6-6',refresh:'M20 7a8 8 0 1 0 0 10 M20 2v5h-5',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12 M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0'
};
const icon = (name, cls='') => `<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name] || paths.file}"/></svg>`;
const nav = [['dashboard','grid','Vue d’ensemble'],['offers','radar','Radar d’offres'],['applications','briefcase','Mes candidatures'],['documents','file','Mes documents'],['companies','building','Entreprises'],['outreach','mail','Mes brouillons'],['intelligence','chart','Mon évolution'],['profile','user','Mon profil']];
const labels = {saved:'À préparer',analyzed:'Analysée',generated:'Documents prêts',archived:'Archivée',active:'Active',closed:'Fermée'};
const docLabels = {cv:'CV personnalisé',letter:'Lettre de motivation',mail:'Email de candidature'};
const state = {page:'dashboard',pagination:1,q:'',source:'',status:'',signal:'priority',profileCategory:'all',overview:null,settings:null,viewVersion:0};
let drawerTrigger = null;
let drawerVersion = 0;
let requestTimer;
const date = value => value ? new Intl.DateTimeFormat('fr-FR',{day:'numeric',month:'short',year:'numeric'}).format(new Date(value)) : 'Non renseignée';
const number = n => new Intl.NumberFormat('fr-FR').format(n || 0);
const sourceName = source => (source || '').replace('snapshot:','').replace(/_/g,' ').replace(/^./, c=>c.toUpperCase());
const locationName = o => {const match=(o.raw_text||'').match(/(?:Location|Lieu|Localisation):\s*([^\n]+)/i);return match ? match[1].slice(0,75) : 'Lieu non renseigné';};
const logo = name => `<span class="company-logo" data-company="${esc((name||'').toLowerCase())}">${esc((name||'?').charAt(0))}${name==='Stripe'?'':name==='Qonto'?'<span hidden>Qonto</span>':''}</span>`;
const badge = s => `<span class="badge ${esc(s)}"><span class="tiny-dot"></span>${esc(labels[s]||s)}</span>`;
const safeURL = value => {try{const u=new URL(value);return ['http:','https:'].includes(u.protocol)?u.href:'#';}catch{return '#';}};
const btn = (text, action, style='btn-primary', ico='plus', attrs='') => `<button class="btn ${style}" data-action="${action}" ${attrs}>${icon(ico)}${text}</button>`;
function toast(message,error=false){const el=document.createElement('div');el.className=`toast${error?' error':''}`;el.textContent=message;$('#toasts').append(el);setTimeout(()=>el.remove(),6500);}
async function api(path, options={}) {
  const token = sessionStorage.getItem('jobapply-token');
  const response = await fetch(`/api${path}`,{...options,headers:{'Content-Type':'application/json',...(token?{Authorization:`Bearer ${token}`} : {}),...options.headers}});
  if(!response.ok){let error;try{error=await response.json();}catch{error={};}const detail=error.detail;const message=Array.isArray(detail)?'Certains champs sont invalides. Vérifiez le texte et le lien de l’offre.':typeof detail==='string'?detail:'Le serveur est momentanément indisponible. Réessayez.';const e=new Error(message);e.status=response.status;throw e;}
  return options.download?response:response.json();
}
const post = (path,payload={}) => api(path,{method:'POST',body:JSON.stringify(payload)});
function heading(eyebrow,title,description,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div><div class="heading-actions">${actions}</div></div>`;}
function empty(ico,title,description,actions=''){return `<div class="empty"><span class="empty-icon">${icon(ico)}</span><h3>${title}</h3><p>${description}</p>${actions}</div>`;}
function pagination(data){const pages=Math.max(1,Math.ceil(data.total/data.page_size));return `<div class="pagination"><span>${data.total?`${number((data.page-1)*data.page_size+1)}–${number(Math.min(data.page*data.page_size,data.total))} sur ${number(data.total)}`:'Aucun résultat'}</span><div class="pagination-controls"><button class="icon-button" data-action="paginate" data-page="${data.page-1}" aria-label="Page précédente" ${data.page<=1?'disabled':''}>${icon('left')}</button><span>Page ${data.page} sur ${pages}</span><button class="icon-button" data-action="paginate" data-page="${data.page+1}" aria-label="Page suivante" ${data.page>=pages?'disabled':''}>${icon('chevron')}</button></div></div>`;}
function searchInput(placeholder='Rechercher un poste, une entreprise…'){return `<div class="search-field">${icon('search')}<input id="list-search" type="search" aria-label="${placeholder}" placeholder="${placeholder}" value="${esc(state.q)}" autocomplete="off"></div>`;}
function offerOpportunityBadge(o){return o.opportunity_id?`<span class="opportunity-chip" title="Opportunité centralisée">OPP-${esc(o.opportunity_id)}${o.opportunity_status?` · ${esc(o.opportunity_status)}`:''}</span>`:'';}
function offerRows(offers){return offers.map(o=>`<button class="offer-row" data-action="offer" data-id="${o.id}">${logo(o.company)}<div class="offer-main"><h3>${esc(o.job_title)}</h3><div class="offer-meta"><span>${esc(o.company)}</span><span>·</span>${icon('pin')}<span>${esc(locationName(o))}</span>${offerOpportunityBadge(o)}</div></div><span class="offer-source">${esc(sourceName(o.source))}</span><span class="row-arrow">${icon('arrow')}</span></button>`).join('');}
function heroArt(){return `<svg class="hero-art" viewBox="0 0 340 280" fill="none" aria-hidden="true"><circle cx="202" cy="137" r="115" stroke="#6f9877" stroke-opacity=".22"/><circle cx="202" cy="137" r="89" stroke="#6f9877" stroke-opacity=".3"/><circle cx="202" cy="137" r="62" stroke="#6f9877" stroke-opacity=".3"/><path d="M78 221 311 43" stroke="#6f9877" stroke-opacity=".25" stroke-dasharray="4 5"/><g transform="rotate(-12 194 125)"><rect x="139" y="77" width="108" height="112" rx="13" fill="#37624e" stroke="#8da97a" stroke-opacity=".4"/><rect x="153" y="92" width="34" height="7" rx="3" fill="#a4bb8b"/><rect x="153" y="112" width="72" height="4" rx="2" fill="#6d8d6a"/><rect x="153" y="124" width="57" height="4" rx="2" fill="#6d8d6a"/><rect x="153" y="143" width="77" height="4" rx="2" fill="#6d8d6a"/><rect x="153" y="155" width="67" height="4" rx="2" fill="#6d8d6a"/><rect x="153" y="167" width="45" height="4" rx="2" fill="#6d8d6a"/></g><rect x="226" y="165" width="40" height="40" rx="12" fill="#d9e9ac" transform="rotate(10 226 165)"/><path d="m233 184 7 8 13-15" stroke="#34583b" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/><circle cx="111" cy="103" r="5" fill="#c7d9a2"/><circle cx="271" cy="73" r="3" fill="#779767"/><path d="M107 184v12m-6-6h12 M274 123v12m-6-6h12" stroke="#92ad72" stroke-width="1.5"/><circle cx="175" cy="31" r="3" fill="#92ad72"/><circle cx="164" cy="240" r="3" fill="#92ad72"/></svg>`;}
async function dashboard(){
 const [overview,offers,profile]=await Promise.all([api('/overview'),api('/offers?page_size=5'),api('/profile')]);state.overview=overview;updateCounts();
 const c=overview.counts; const identity=profile.master_cv?.profile||{};const name=(identity.name||'Akim').split(' ')[0];setName(identity.name);
 const metrics=[['radar','Offres à explorer',c.offers,`${number(c.active_offers)} active${c.active_offers>1?'s':''} · archives incluses`],['briefcase','Candidatures',c.applications,`${number(overview.statuses.saved)} à préparer`],['file','Documents créés',c.documents,'Vos CV, lettres et emails'],['building','Entreprises suivies',c.companies,'Votre écosystème d’opportunités']];
 return heading('VOTRE PROCHAIN CHAPITRE',`Bonjour ${esc(name)} <span style="font-size:24px;font-weight:400">☀</span>`,'Les bonnes opportunités. Des candidatures qui vous ressemblent.',btn('Ajouter une offre','create'))+
 `<section class="hero"><div class="hero-copy"><div class="hero-label">${icon('spark')} De l’opportunité à la candidature</div><h2>Votre prochaine étape commence ici.</h2><p>Repérez une offre, révélez vos atouts, préparez une candidature sur mesure.</p><a class="btn btn-lime" href="#offers">Explorer les opportunités ${icon('arrow')}</a></div>${heroArt()}</section>`+
 `<section class="metrics" aria-label="Votre activité">${metrics.map(([i,label,n,caption])=>`<div class="metric"><div class="metric-top"><span>${label}</span><span class="metric-icon">${icon(i)}</span></div><div class="metric-bottom"><span class="metric-number">${number(n)}</span></div><div class="metric-caption"><span class="tiny-dot"></span>${caption}</div></div>`).join('')}</section>`+
 `<div class="dashboard-grid"><div><section class="panel"><div class="panel-head"><div><h2>À découvrir dans votre radar</h2><p>Un premier regard sur vos opportunités.</p></div><a class="text-link" href="#offers">Tout explorer ${icon('arrow')}</a></div>${offers.total?offerRows(offers.items):empty('radar','Votre radar attend ses premières offres','Ajoutez une offre ou explorez les archives disponibles.',btn('Importer les archives','import','btn-primary','download'))}<div class="panel-foot"><span>${icon('clock')} ${offers.items.some(o=>o.source.startsWith('snapshot:'))?'Archives du 5 septembre 2026 · disponibilité à vérifier':'Données enregistrées dans votre espace'}</span><span>${number(offers.total)} offres</span></div></section><div class="insight-card">${icon('shield')}<div><h3>Votre expérience reste la source de vérité.</h3><p>L’IA adapte votre candidature à partir de votre profil, sans inventer de compétences.</p></div><a href="#profile" class="text-link">Mon profil ${icon('arrow')}</a></div>${overview.recent_applications.length?`<section class="panel mt"><div class="panel-head"><h2>Reprendre une candidature</h2><a class="text-link" href="#applications">Tout voir ${icon('arrow')}</a></div>${overview.recent_applications.slice(0,3).map(a=>`<button class="offer-row" data-action="application" data-id="${a.id}">${logo(a.company)}<div class="offer-main"><h3>${esc(a.job_title||'Offre à analyser')}</h3><div class="offer-meta">${esc(a.company||'Entreprise à préciser')}</div></div>${badge(a.status)}</button>`).join('')}</section>`:''}</div><aside class="dashboard-aside"><div class="section-stack"><section class="panel"><div class="panel-head"><div><h2>À vous de jouer</h2><p>Trois étapes vers votre prochain poste.</p></div>${icon('spark')}</div><div class="journey">${[['user','Un profil qui vous ressemble',`${number(c.profile_blocks)} éléments pour raconter votre parcours.`,c.profile_blocks>0],['radar','L’opportunité qui vous correspond','Explorez les offres et gardez vos favoris.',c.applications>0],['file','Une candidature bien préparée','Un CV, une lettre, un email adaptés.',c.documents>0]].map(([i,t,d,done],idx)=>`<div class="journey-step"><span class="step-icon ${done?'step-done':''}">${done?icon('check'):String(idx+1).padStart(2,'0')}</span><div><h3>${t}</h3><p>${d}</p></div></div>`).join('')}<a class="btn" href="#${c.applications?'applications':'offers'}">${c.applications?'Préparer mes candidatures':'Trouver une opportunité'} ${icon('arrow')}</a></div></section><section class="panel"><div class="panel-head"><h2>Vos sources d’opportunités</h2>${icon('radar')}</div><div class="sources">${overview.sources.slice(0,5).map(s=>`<div class="source-row"><div class="source-label"><span>${esc(sourceName(s.source))}</span><span>${number(s.count)}</span></div><div class="bar-track"><div class="bar-fill" style="width:${Math.max(2,s.count/Math.max(1,c.offers)*100)}%"></div></div></div>`).join('')||'<p class="source-note">Les sources apparaîtront après votre premier import.</p>'}<p class="source-note">${overview.sources.some(s=>s.source.startsWith('snapshot:'))?'Les archives sont datées. Consultez l’offre d’origine avant de postuler.':'Les volumes reflètent les offres enregistrées, sans estimation.'}</p></div></section></div></aside></div>`;
}
async function offersPage(){
 const params=new URLSearchParams({page:state.pagination,page_size:15,q:state.q});if(state.source)params.set('source',state.source);if(state.status)params.set('status',state.status);if(state.signal)params.set('signal',state.signal);
 const [data,overview]=await Promise.all([api(`/offers?${params}`),api('/overview')]);state.overview=overview;updateCounts();
 return heading('DÉCOUVRIR','Votre radar d’offres','Les offres les plus récentes et les plus proches de votre profil d’abord. Les anciennes restent utilisées pour l’analyse marché.',btn('Ajouter une offre','create'))+
 (overview.sources.some(s=>s.source.startsWith('snapshot:'))?`<div class="archive-notice">${icon('clock')}<span>Les offres marquées « Archive » proviennent de la collecte du <strong>5 septembre 2026</strong>. Leur disponibilité actuelle reste à vérifier sur le site d’origine.</span></div>`:'')+
 `<section class="panel"><div class="toolbar">${searchInput()}<select id="source-filter" aria-label="Filtrer par source"><option value="">Toutes les sources</option>${overview.sources.map(s=>`<option value="${esc(s.source)}" ${state.source===s.source?'selected':''}>${esc(sourceName(s.source))}${s.source.startsWith('snapshot:')?' · archives':''}</option>`).join('')}</select><select id="status-filter" aria-label="Filtrer par disponibilité"><option value="">Toutes les offres</option>${[['active','Actives'],['archived','Archives'],['closed','Fermées']].map(([v,l])=>`<option value="${v}" ${state.status===v?'selected':''}>${l}</option>`).join('')}</select><select id="signal-filter" aria-label="Filtrer par signal">${[['priority','Prioritaires'],['recent','Récentes 48h'],['potential','Potentiel'],['noise','Bruit'],['','Tout le stock']].map(([v,l])=>`<option value="${v}" ${state.signal===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="list-info"><span><strong>${number(data.total)}</strong> opportunités${state.q?' correspondant à votre recherche':''}</span><span>${state.signal==='priority'?'Signal fort en premier':state.signal==='recent'?'Nouvelles offres en premier':'Tri par score puis fraîcheur'}</span></div>${data.total?`<div class="table-wrap"><table><thead><tr><th>Poste & entreprise</th><th class="hide-mobile">Signal</th><th>Source</th><th class="hide-mobile">Fraîcheur</th><th><span class="muted">Dossier</span></th></tr></thead><tbody>${data.items.map(o=>`<tr><td><div class="table-job">${logo(o.company)}<button data-action="offer" data-id="${o.id}"><strong>${esc(o.job_title)}</strong><small>${esc(o.company)}</small></button></div></td><td class="hide-mobile"><strong>${esc(o.signal_score)}/100</strong><small class="muted" style="display:block;margin-top:5px">${esc((o.signal_reasons||[])[0]||o.signal_role_family)}</small></td><td><span class="offer-source" style="display:inline-block">${esc(sourceName(o.source))}</span>${o.source.startsWith('snapshot:')?'<small class="muted" style="display:block;margin-top:5px">Archive</small>':''}</td><td class="hide-mobile"><span class="badge ${o.signal_tier==='priority'?'generated':o.signal_tier==='noise'?'archived':'analyzed'}">${esc(o.recency==='new'?'Nouvelle':o.recency==='fresh'?'Fraîche':'Stock')}</span></td><td><div class="dossier-cell">${offerOpportunityBadge(o)||'<span class="muted">Non lié</span>'}<button class="icon-button ${o.saved_application_id?'active':''}" data-action="${o.saved_application_id?'application':'save-offer'}" data-id="${o.saved_application_id||o.id}" aria-label="${o.saved_application_id?'Ouvrir la candidature':'Enregistrer cette offre'}">${icon(o.saved_application_id?'check':'bookmark')}</button></div></td></tr>`).join('')}</tbody></table></div>`:empty('search',state.q||state.source||state.status?'Aucune offre ne correspond':'Votre radar est prêt',state.q||state.source||state.status?'Essayez un intitulé plus large ou retirez un filtre.':'Importez les archives du dépôt ou ajoutez une offre qui vous intéresse.',state.q||state.source||state.status?btn('Effacer les filtres','reset-filters','btn','refresh'):btn('Importer les archives','import','btn-primary','download'))}${pagination(data)}</section>`;
}
async function applicationsPage(){if(state.applicationView==='tracking')return trackingPage();const params=new URLSearchParams({page:state.pagination,page_size:15,q:state.q});if(state.status)params.set('status',state.status);const data=await api(`/applications?${params}`);return heading('PASSER À L’ACTION','Mes candidatures','Chaque opportunité, son dossier. Avancez à votre rythme.',btn('Nouvelle candidature','create'))+applicationTabs()+`<section class="panel"><div class="toolbar">${searchInput('Rechercher une candidature…')}<select id="status-filter" aria-label="Filtrer par statut"><option value="">Tous les statuts</option>${['saved','analyzed','generated','archived'].map(s=>`<option value="${s}" ${state.status===s?'selected':''}>${labels[s]}</option>`).join('')}</select></div>${data.total?`<div class="table-wrap"><table><thead><tr><th>Candidature</th><th>Statut</th><th class="hide-mobile">Adéquation</th><th class="hide-mobile">Dernière activité</th><th></th></tr></thead><tbody>${data.items.map(a=>`<tr><td><div class="table-job">${logo(a.company)}<button data-action="application" data-id="${a.id}"><strong>${esc(a.job_title||'Offre à analyser')}</strong><small>${esc(a.company||'Entreprise à préciser')}</small></button></div></td><td>${badge(a.status)}</td><td class="hide-mobile">${a.match_score===null?'<span class="muted">À analyser</span>':`<strong>${esc(a.match_score)}/10</strong>`}</td><td class="muted hide-mobile">${date(a.updated_at)}</td><td><button class="icon-button" aria-label="Ouvrir la candidature" data-action="application" data-id="${a.id}">${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div>`:empty('briefcase','Votre prochaine candidature commence ici','Enregistrez une offre depuis le radar ou ajoutez le texte d’une annonce.',`<a class="btn btn-primary" href="#offers">${icon('radar')}Explorer le radar</a>`)}${pagination(data)}</section>`;}
async function companiesPage(){const data=await api(`/companies?${new URLSearchParams({q:state.q,page:state.pagination,page_size:12})}`);return heading('MIEUX CIBLER','Les entreprises de votre radar','Découvrez où se trouvent les opportunités et les contacts déjà identifiés.')+`<div class="toolbar panel" style="margin-bottom:20px">${searchInput('Rechercher une entreprise…')}<span class="muted" style="font-size:11px">${number(data.total)} entreprises</span></div>${data.total?`<div class="card-grid">${data.items.map(c=>`<button class="panel company-card" data-action="company" data-id="${c.id}"><div class="company-card-top">${logo(c.name)}${icon('external')}</div><h3>${esc(c.name)}</h3><p>${c.website?esc(new URL(safeURL(c.website),'http://localhost').hostname):'Entreprise identifiée dans le radar'}</p><div class="company-card-bottom"><span>${number(c.offer_count)} offres enregistrées</span><span>${number(c.contact_count)} contacts</span></div></button>`).join('')}</div>${pagination(data)}`:`<section class="panel">${empty('building','Vos entreprises apparaîtront ici','Explorez les archives pour découvrir les entreprises de votre radar.',btn('Importer les archives','import','btn-primary','download'))}</section>`}`;}
async function documentsPage(){const data=await api(`/documents?${new URLSearchParams({q:state.q,page:state.pagination,page_size:12})}`);return heading('PRÊT À CANDIDATER','Mes documents','Retrouvez les CV, lettres et emails préparés pour chaque candidature.')+`<div class="toolbar panel" style="margin-bottom:20px">${searchInput('Rechercher un document ou une entreprise…')}<span class="muted" style="font-size:11px">${number(data.total)} documents</span></div>${data.total?`<div class="card-grid">${data.items.map(d=>`<article class="panel document-card"><span class="document-type">${icon(d.document_type==='mail'?'mail':'file')}</span><span class="badge">${docLabels[d.document_type]||esc(d.document_type)}</span><h3 style="margin-top:13px">${esc(d.job_title||d.filename)}</h3><p>${esc(d.company||'Candidature')} · ${date(d.created_at)}</p><div class="card-actions">${btn('Aperçu','document','btn-small','eye',`data-id="${d.id}"`)}${btn('Télécharger','download','btn-small btn-ghost','download',`data-id="${d.id}"`)}</div></article>`).join('')}</div>${pagination(data)}`:`<section class="panel">${empty('file','La bonne candidature commence par les bons mots','Analysez une offre, puis générez un CV, une lettre et un email adaptés à partir de votre profil.',`<a class="btn btn-primary" href="#applications">${icon('briefcase')}Voir mes candidatures</a>`)}</section>`}`;}
async function profilePage(){const data=await api('/profile');const master=data.master_cv||{};const identity=master.profile||{};setName(identity.name);const categories={all:'Tout le profil',experience:'Expériences',project:'Projets',skill:'Compétences',education:'Formation',language:'Langues',certification:'Certifications',tool:'Outils'};const blocks=data.blocks.filter(b=>state.profileCategory==='all'||b.category===state.profileCategory);return heading('VOTRE SOURCE DE VÉRITÉ','Mon profil','Une base fidèle à votre parcours. Le point de départ de chaque candidature.',`<span class="badge">${icon('shield')} Profil vérifié</span>`)+`<div class="profile-layout"><aside class="panel profile-summary"><span class="profile-avatar">${esc((identity.name||'Akim Guentas').split(' ').map(n=>n[0]).slice(0,2).join(''))}</span><h2>${esc(identity.name||'Mon profil')}</h2><p>${esc(identity.title_short||identity.title||identity.headline||'Data, IA & automatisation')}</p><span class="badge">${number(data.blocks.length)} blocs de profil</span><span class="badge">Master CV V3</span><div class="drawer-section mt"><h3>Un profil, plusieurs angles</h3><p>Le moteur sélectionne les expériences pertinentes et adapte leur présentation à chaque offre.</p></div><div class="drawer-section"><h3>Les faits restent les faits.</h3><p>Les expériences, les niveaux de maîtrise et les résultats chiffrés proviennent du profil source.</p></div></aside><section class="panel"><div class="toolbar"><h2 style="flex:1">Votre parcours en détail</h2><select id="profile-category" aria-label="Filtrer les éléments du profil">${Object.entries(categories).map(([v,l])=>`<option value="${v}" ${state.profileCategory===v?'selected':''}>${l}</option>`).join('')}</select></div>${blocks.map(b=>`<article class="profile-block"><div class="flex-between"><span class="badge">${esc(categories[b.category]||b.category)}</span><span class="muted" style="font-size:9px">${b.truth_level==='verified'?'Source vérifiée':b.truth_level==='learning'?'En apprentissage':'Déclaré'}</span></div><h3>${esc(b.title)}</h3><p>${esc(b.content)}</p>${b.technologies?.length?`<div class="tags">${b.technologies.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div>`:''}</article>`).join('')||empty('user','Aucun élément dans cette catégorie','Le profil source est importé lors de l’initialisation locale.')}<div class="panel-foot">Le Master CV est conservé comme source de référence. Modification dans les fichiers de profil du projet.</div></section></div>`;}
async function intelligencePage(){const data=await api('/intelligence');if(!data.total_offers_analyzed)return heading('CONTINUER À GRANDIR','Mon évolution','Transformez vos analyses de candidatures en pistes de progression concrètes.')+`<section class="panel">${empty('chart','Chaque candidature vous apprend quelque chose','Après votre première analyse, retrouvez ici vos points forts, vos gaps récurrents et un plan d’action priorisé.',`<a href="#applications" class="btn btn-primary">${icon('spark')}Analyser une candidature</a>`)}</section>`;const signals=data.market_signals||{};const memory=data.learning_memory||{};const priorities=data.gap_priorities||[];const actions=data.action_plan||[];const strengths=signals.top_strengths||[];const requested=signals.top_requested_skills||[];const roles=(data.positioning_insights||{}).best_role_families||[];return heading('CONTINUER À GRANDIR','Mon évolution','Ce tableau transforme les offres analysées, tes candidatures et les retours du marché en leviers concrets.')+`<div class="archive-notice">${icon('info')}Analyse fondée sur <strong>${number(data.total_offers_analyzed)} offres/candidatures analysées</strong>, ${number(memory.gap_events_recorded)} signaux de gaps et ${number(memory.signals_used)} signaux utilisés pour apprendre.</div><section class="metrics intelligence-metrics" aria-label="Mémoire d’apprentissage">${[['chart','Offres analysées',data.total_offers_analyzed,'Échantillon utile'],['search','Signaux marché',memory.signals_used||0,'Forces + gaps détectés'],['spark','Actions proposées',actions.length,'Priorisées par impact'],['briefcase','Gaps critiques',priorities.filter(g=>g.priority==='high').length,'À traiter en premier']].map(([i,label,n,caption])=>`<div class="metric"><div class="metric-top"><span>${label}</span><span class="metric-icon">${icon(i)}</span></div><div class="metric-bottom"><span class="metric-number">${number(n)}</span></div><div class="metric-caption"><span class="tiny-dot"></span>${caption}</div></div>`).join('')}</section><div class="career-grid"><section class="panel settings-panel"><h2>Ce que le marché demande</h2><p>Compétences qui reviennent dans les offres analysées et qui servent au matching.</p>${requested.slice(0,8).map(s=>`<div class="setting-row"><span>${esc(s.skill)}</span><span class="badge">${s.frequency} · ${s.percentage}%</span></div>`).join('')||'<p>Aucun signal marché pour le moment.</p>'}</section><section class="panel settings-panel"><h2>Ce que ton profil prouve déjà</h2><p>Forces extraites des analyses et réutilisables dans les CV ciblés.</p>${strengths.slice(0,8).map(s=>`<div class="setting-row">${icon('check')}<span style="flex:1">${esc(s.skill)}</span><span class="badge">${s.frequency}</span></div>`).join('')||'<p>Aucune force consolidée pour le moment.</p>'}</section></div><section class="panel mt"><div class="panel-head"><div><h2>Plan d’action priorisé</h2><p>Ce qu’il faut apprendre, prouver ou repositionner pour améliorer les prochaines candidatures.</p></div>${icon('spark')}</div><div class="action-plan-list">${actions.map(a=>`<article class="action-card"><div class="action-rank">${a.rank}</div><div><div class="action-title"><strong>${esc(a.skill)}</strong><span class="badge ${a.priority==='high'?'generated':'saved'}">${esc(a.priority)}</span></div><p>${esc(a.action)}</p><small>${esc(a.why_now)} · Effort estimé ${esc(a.estimated_effort)}</small></div></article>`).join('')||'<p class="source-note">Aucune action prioritaire tant que les gaps ne sont pas enregistrés.</p>'}</div></section><div class="career-grid mt"><section class="panel settings-panel"><h2>Gaps à surveiller</h2><p>Classés par fréquence, importance et confiance.</p>${priorities.slice(0,8).map(g=>`<div class="setting-row"><span>${esc(g.skill)}</span><span class="badge">score ${esc(g.impact_score)}</span></div>`).join('')||'<p>Aucun gap prioritaire.</p>'}</section><section class="panel settings-panel"><h2>Positionnement</h2><p>${esc((data.positioning_insights||{}).message||'Les angles se préciseront après plusieurs analyses.')}</p>${roles.map(r=>`<div class="setting-row"><span>${esc(r.role_family)}</span><span class="badge">${esc(r.average_match_score)}/10 · ${r.sample_size}</span></div>`).join('')||'<p>Aucune famille de rôle consolidée.</p>'}</section></div>`;}
async function settingsPage(){const s=await api('/settings');state.settings=s;return heading('UN ESPACE À VOTRE IMAGE','Réglages & connexions','Vérifiez votre configuration et retrouvez les informations de votre espace.')+`<div class="settings-grid"><section class="panel settings-panel"><h2>Vos connexions</h2><p>L’état ci-dessous indique les paramètres présents. Il ne garantit pas la validité des clés.</p>${[['Analyse & génération IA','OpenAI · analyse, CV, lettre et email',s.ai_configured],['Bot Telegram','Votre interface de candidature existante',s.telegram_configured],['Base de données',s.database_backend==='sqlite'?'SQLite · stockage local':'PostgreSQL · stockage connecté',true],['Accès protégé',s.access_protected?'Clé d’accès requise':'Accès limité à la machine locale',s.access_protected]].map(([t,d,ok])=>`<div class="setting-row"><div><strong>${t}</strong><small>${d}</small></div><span class="badge ${ok?'generated':'saved'}">${ok?'Configuré':'Local / à configurer'}</span></div>`).join('')}<div class="archive-notice mt">${icon('info')}Aucune candidature ni aucun email n’est envoyé automatiquement.</div></section><section class="panel settings-panel"><h2>Activer les fonctionnalités IA</h2><p>Ajoutez votre clé dans le fichier <strong>.env</strong> du projet, puis redémarrez le serveur. Elle n’est jamais affichée dans l’interface.</p><code class="code-snippet">OPENAI_API_KEY=votre_cle\nCANDIDATE_NAME=Votre nom\nCANDIDATE_EMAIL=votre@email.fr\nWEB_USER_ID=${esc(s.web_user_id)}</code><p class="mt">Pour retrouver les dossiers Telegram, utilisez votre identifiant Telegram comme WEB_USER_ID.</p><a class="btn" href="/docs" target="_blank" rel="noopener">${icon('external')}Documentation de l’API</a></section><section class="panel settings-panel"><h2>Explorer les archives du dépôt</h2><p>Importez la collecte du 5 septembre 2026 dans votre radar. L’import conserve les dates d’origine et ignore les offres déjà présentes.</p>${btn('Importer les archives','import','btn-primary','download')}<p class="source-note">Les offres importées portent le statut « Archivée ». La collecte automatique reste gérée par le scheduler du projet.</p></section><section class="panel settings-panel"><h2>Clé d’accès à cet espace</h2><p>Si le serveur est protégé, saisissez sa clé WEB_ACCESS_TOKEN. Elle reste dans la session de cet onglet.</p><form id="access-form"><div class="form-field"><label for="access-token">Clé d’accès</label><input type="password" id="access-token" name="token" autocomplete="off" placeholder="Votre clé d’accès"></div><div class="form-actions">${btn('Déconnecter cet onglet','logout','btn-ghost','close')}<button class="btn btn-primary" type="submit">Enregistrer</button></div></form></section></div>`;}
const pages={dashboard,offers:offersPage,applications:applicationsPage,companies:companiesPage,documents:documentsPage,profile:profilePage,intelligence:intelligencePage,settings:settingsPage};
function setName(name){if(!name)return;$('#sidebar-name').textContent=name;const initials=name.split(' ').map(w=>w[0]).slice(0,2).join('');$('.top-avatar').textContent=initials;$('.user-card .avatar').textContent=initials;}
function updateCounts(){if(!state.overview)return;for(const page of ['offers','applications']){const el=$(`[data-nav="${page}"] .nav-count`);if(el)el.textContent=number(state.overview.counts[page]);}}
async function render({preserveFocus=false}={}){const version=++state.viewVersion;const focused=preserveFocus&&document.activeElement?.id;const selection=focused&&document.activeElement.selectionStart;const scroll=preserveFocus?window.scrollY:0;const page=state.page;$('#breadcrumb').textContent=nav.find(n=>n[0]===page)?.[2]||'Réglages';document.title=`${$('#breadcrumb').textContent} — Job Apply`;document.querySelectorAll('[data-nav]').forEach(el=>{el.classList.toggle('active',el.dataset.nav===page);if(el.dataset.nav===page)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});$('#settings-link').classList.toggle('active',page==='settings');if(!preserveFocus)$('#main').innerHTML='<div class="page-loading"><span class="spinner"></span>Un instant, votre espace se prépare…</div>';try{const html=await pages[page]();if(version!==state.viewVersion)return;$('#main').innerHTML=html;if(focused&&$(`#${focused}`)){const el=$(`#${focused}`);el.focus();if(el.type==='search')el.setSelectionRange(selection,selection);}if(preserveFocus)window.scrollTo(0,scroll);}catch(e){if(version!==state.viewVersion)return;$('#main').innerHTML=e.status===401||e.status===403?heading('ACCÈS PERSONNEL','Votre espace est protégé','Connectez cet onglet avec la clé d’accès du serveur.')+`<section class="panel settings-panel" style="max-width:480px"><form id="access-form"><div class="form-field"><label for="access-token">Clé d’accès</label><input type="password" id="access-token" name="token" autocomplete="off" required autofocus></div><p class="form-error">${esc(e.message)}</p><div class="form-actions"><button class="btn btn-primary" type="submit">Ouvrir mon espace ${icon('arrow')}</button></div></form></section>`:`<section class="error-card"><h2>Votre espace n’a pas pu être chargé</h2><p>${esc(e.message)}</p>${btn('Réessayer','retry','btn-primary','refresh')}</section>`;}}
function navigate(){closeDrawer();const next=location.hash.slice(1).split('?')[0]||'dashboard';state.page=pages[next]?next:'dashboard';state.applicationView=new URLSearchParams(location.hash.split('?')[1]||'').get('view')==='tracking'?'tracking':'preparation';state.pagination=1;state.q='';state.source='';state.status='';$('#sidebar').classList.remove('open');$('#menu-button').setAttribute('aria-expanded','false');render();}
function closeDrawer(){drawerVersion++;$('#drawer').hidden=true;$('#drawer-backdrop').hidden=true;document.body.style.overflow='';drawerTrigger?.focus?.();}
function openDrawer(){drawerTrigger=document.activeElement;$('#drawer').hidden=false;$('#drawer-backdrop').hidden=false;document.body.style.overflow='hidden';$('#drawer').innerHTML='<div class="page-loading"><span class="spinner"></span>Chargement du détail…</div>';$('#drawer').focus();return ++drawerVersion;}
const drawerTop = label => `<div class="drawer-toolbar"><span>${label}</span><button class="icon-button" data-action="close-drawer" aria-label="Fermer le détail">${icon('close')}</button></div>`;
async function detail(kind,id,keepOpen=false){const version=keepOpen?++drawerVersion:openDrawer();try{const data=await api(`/${kind==='offer'?'offers':kind==='application'?'applications':kind==='company'?'companies':'documents'}/${id}`);if(version!==drawerVersion)return;$('#drawer').dataset.kind=kind;$('#drawer').dataset.id=id;let html='';
 if(kind==='offer'){const archived=data.source.startsWith('snapshot:');html=drawerTop('RADAR · DÉTAIL DE L’OFFRE')+`<div class="drawer-title">${logo(data.company)}<div><h2>${esc(data.job_title)}</h2><p>${esc(data.company)}</p></div></div><div class="detail-grid"><div><small>LOCALISATION</small><strong>${esc(locationName(data))}</strong></div><div><small>SOURCE</small><strong>${esc(sourceName(data.source))}</strong></div><div><small>ENREGISTRÉE LE</small><strong>${date(data.created_at)}</strong></div><div><small>DISPONIBILITÉ</small>${badge(data.status)}</div></div>${archived?'<div class="archive-notice mt">Cette offre est une archive. Vérifiez sa disponibilité sur le site d’origine avant de préparer votre candidature.</div>':''}<div class="drawer-actions">${data.saved_application_id?btn('Ouvrir ma candidature','application','btn-primary','briefcase',`data-id="${data.saved_application_id}"`):btn('Préparer ma candidature','save-offer','btn-primary','bookmark',`data-id="${id}"`)}<a class="btn" href="${esc(safeURL(data.job_url))}" target="_blank" rel="noopener noreferrer">Voir l’offre d’origine ${icon('external')}</a></div>${data.required_skills?.length?`<div class="drawer-section"><h3>Compétences mentionnées</h3><div class="tags">${data.required_skills.map(s=>`<span class="tag">${esc(s)}</span>`).join('')}</div></div>`:''}<div class="drawer-section"><h3>L’offre en détail</h3><div class="offer-description">${esc(data.raw_text||'Le texte de cette offre n’a pas été extrait. Consultez le site d’origine.')}</div></div>`;
 }else if(kind==='application'){html=drawerTop('VOTRE DOSSIER DE CANDIDATURE')+`<div class="drawer-title">${logo(data.company)}<div><h2>${esc(data.job_title||'Offre à analyser')}</h2><p>${esc(data.company||'Entreprise à préciser')}</p></div></div><div class="flex-between">${badge(data.status)}<select id="application-status" data-id="${id}" aria-label="Statut de la candidature">${['saved','analyzed','generated','archived'].map(s=>`<option value="${s}" ${data.status===s?'selected':''}>${labels[s]}</option>`).join('')}</select></div>${data.match_score!==null?`<div class="score-box"><span class="score-number">${esc(data.match_score)}<span style="font-size:14px">/10</span></span><div><h3>Adéquation avec votre profil</h3><p>${esc(data.recommended_angle||'Analyse personnalisée')}</p></div></div>`:''}<div class="drawer-actions">${btn(data.analysis?'Actualiser l’analyse':'Analyser cette offre','analyze','btn-primary','spark',`data-id="${id}"`)}${data.source_url?`<a class="btn" href="${esc(safeURL(data.source_url))}" target="_blank" rel="noopener noreferrer">Offre d’origine ${icon('external')}</a>`:''}</div><div id="operation-status" aria-live="polite"></div>${data.analysis?`${analysisSection('Vos points forts',data.analysis.strengths)}${analysisSection('Points à prendre en compte',data.analysis.missing_points)}${analysisSection('Missions principales',data.analysis.missions)}<section class="drawer-section"><h3>Préparer vos documents</h3><p>Votre profil sert de référence. Relisez les documents avant de les utiliser.</p><div class="drawer-actions">${btn('Dossier complet','generate','btn-primary','spark',`data-id="${id}" data-types="cv,letter,mail"`)}${['cv','letter','mail'].map(t=>btn({cv:'CV',letter:'Lettre',mail:'Email'}[t],'generate','btn-small','file',`data-id="${id}" data-types="${t}"`)).join('')}</div></section>`:'<div class="archive-notice">Analysez cette offre pour identifier vos atouts et préparer vos documents personnalisés.</div>'}<section class="drawer-section"><h3>Documents du dossier (${data.documents.length})</h3>${data.documents.length?data.documents.map(d=>`<div class="setting-row"><button class="text-link" data-action="document" data-id="${d.id}">${icon(d.document_type==='mail'?'mail':'file')}${docLabels[d.document_type]}</button><button class="icon-button" data-action="download" data-id="${d.id}" aria-label="Télécharger ${docLabels[d.document_type]}">${icon('download')}</button></div>`).join(''):'<p>Vos documents apparaîtront ici après génération.</p>'}</section><details class="drawer-section"><summary>Texte de l’offre</summary><div class="offer-description mt">${esc(data.raw_offer)}</div></details>`;
 }else if(kind==='company'){html=drawerTop('VOTRE RADAR · ENTREPRISE')+`<div class="drawer-title">${logo(data.name)}<div><h2>${esc(data.name)}</h2><p>${data.offers.length} offres · ${data.contacts.length} contacts identifiés</p></div></div>${data.website?`<a class="btn" href="${esc(safeURL(data.website))}" target="_blank" rel="noopener noreferrer">Site de l’entreprise ${icon('external')}</a>`:''}<div class="drawer-section mt"><h3>Contacts identifiés</h3>${data.contacts.length?data.contacts.map(c=>`<div class="setting-row"><div><strong>${esc(c.contact_name)}</strong><small>${esc(c.role_raw)}</small>${c.email?`<small>${esc(c.email)}</small>`:''}<small>${esc(c.verification_status)}</small></div><a class="text-link" href="${esc(safeURL(c.source_url))}" target="_blank" rel="noopener noreferrer">Source ${icon('external')}</a></div>`).join(''):'<p>Aucun contact vérifié enregistré pour cette entreprise.</p>'}</div><div class="drawer-section"><h3>Offres enregistrées (${data.offers.length})</h3>${offerRows(data.offers)}</div>`;
 }else{html=drawerTop(docLabels[data.document_type]||'DOCUMENT')+`<h2 style="margin-bottom:12px">${esc(data.job_title||data.filename)}</h2><p class="muted" style="font-size:12px">${esc(data.company)} · ${date(data.created_at)}</p><div class="drawer-actions">${btn('Télécharger','download','btn-primary','download',`data-id="${id}"`)}${data.document_type==='mail'?btn('Copier le texte','copy-document','btn','file',`data-id="${id}"`):''}</div><p class="progress-note" style="margin-bottom:16px">Document généré automatiquement : vérifiez les informations avant utilisation.</p>${data.document_type==='mail'?`<div class="mail-preview">${esc(data.content)}</div>`:'<iframe class="document-preview" title="Aperçu du document" sandbox=""></iframe>'}`;}
 $('#drawer').innerHTML=html;if(kind==='document'&&data.document_type!=='mail')$('.document-preview').srcdoc=`<meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; img-src data:">${data.content}`;
 }catch(e){if(version!==drawerVersion)return;$('#drawer').innerHTML=drawerTop('DÉTAIL')+empty('info','Impossible d’ouvrir ce détail',esc(e.message));}}
function analysisSection(title,items){if(!Array.isArray(items)||!items.length)return '';return `<section class="drawer-section"><h3>${title}</h3><ul>${items.map(i=>`<li>${esc(typeof i==='string'?i:i.skill||i.description||JSON.stringify(i))}</li>`).join('')}</ul></section>`;}
function createModal(){const m=$('#modal');m.innerHTML=`<div class="dialog-head"><h2 id="modal-title">Une nouvelle opportunité</h2><button class="icon-button" data-action="close-modal" aria-label="Fermer">${icon('close')}</button></div><p class="dialog-intro">Collez le texte de l’annonce pour ouvrir un dossier. Vous pourrez ensuite l’analyser et préparer vos documents.</p><form id="create-form"><div class="form-row"><div class="form-field"><label for="job-title">Intitulé du poste</label><input id="job-title" name="job_title" placeholder="Ex. Data Analyst" maxlength="255"></div><div class="form-field"><label for="company-name">Entreprise</label><input id="company-name" name="company" placeholder="Ex. Qonto" maxlength="255"></div></div><div class="form-field"><label for="offer-text">Texte de l’offre <span aria-hidden="true">*</span></label><textarea id="offer-text" name="raw_offer" required maxlength="100000" placeholder="Missions, compétences recherchées, description du poste…"></textarea><small>Copiez le contenu de l’annonce pour obtenir une analyse précise.</small></div><div class="form-field"><label for="offer-url">Lien de l’annonce <span class="muted">(facultatif)</span></label><input id="offer-url" type="url" name="source_url" placeholder="https://…" maxlength="2000"></div><p class="form-error" id="create-error" role="alert"></p><div class="form-actions"><button class="btn" type="button" data-action="close-modal">Annuler</button><button class="btn btn-primary" type="submit">${icon('plus')}Créer mon dossier</button></div></form>`;m.showModal();$('#job-title').focus();}
async function runAI(button,kind){const id=button.dataset.id;const region=$('#operation-status');const actions=$('#drawer').querySelectorAll('button[data-action="analyze"],button[data-action="generate"]');actions.forEach(b=>b.disabled=true);if(region)region.innerHTML=`<div class="loading-note"><span class="spinner"></span>${kind==='analyze'?'Analyse de l’offre et de votre profil…':'Préparation de vos documents…'}</div><p class="progress-note">Cela peut prendre quelques minutes. Vous pouvez continuer à explorer votre espace.</p>`;try{const result=await post(`/applications/${id}/${kind}`,kind==='generate'?{document_types:button.dataset.types.split(',')}:{});if(kind==='generate'&&result.status==='full_failure')throw new Error('Aucun document n’a pu être généré. Vérifiez la configuration IA et réessayez.');toast(kind==='analyze'?'Analyse terminée. Votre dossier est prêt à être préparé.':result.status==='partial_success'?'Certains documents sont prêts. Vous pouvez relancer les documents manquants.':'Vos documents sont prêts à être relus.');if(!$('#drawer').hidden&&$('#drawer').dataset.kind==='application'&&$('#drawer').dataset.id===id)await detail('application',id,true);render({preserveFocus:true});}catch(e){if(region?.isConnected)region.innerHTML=`<p class="form-error">${esc(e.message)}</p><a class="text-link" href="#settings">Vérifier les réglages ${icon('arrow')}</a>`;toast(e.message,true);}finally{actions.forEach(b=>b.disabled=false);}}
async function downloadDocument(id){const response=await api(`/documents/${id}/download`,{download:true});const blob=await response.blob();const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=response.headers.get('content-disposition')?.match(/filename="([^"]+)"/)?.[1]||`document-${id}.html`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('click',async event=>{const el=event.target.closest('[data-action]');if(!el||el.disabled)return;const action=el.dataset.action;try{switch(action){case 'create':createModal();break;case 'close-modal':$('#modal').close();break;case 'close-drawer':closeDrawer();break;case 'retry':render();break;case 'offer':case 'application':case 'company':case 'document':await detail(action,el.dataset.id);break;case 'paginate':state.pagination=Number(el.dataset.page);render({preserveFocus:true});break;case 'reset-filters':state.q='';state.source='';state.status='';state.signal='priority';state.pagination=1;render();break;case 'save-offer':{el.disabled=true;const result=await post(`/offers/${el.dataset.id}/save`);toast('Offre enregistrée dans vos candidatures.');await detail('application',result.id);render({preserveFocus:true});break;}case 'analyze':case 'generate':await runAI(el,action);break;case 'download':await downloadDocument(el.dataset.id);break;case 'copy-document':{const doc=await api(`/documents/${el.dataset.id}`);await navigator.clipboard.writeText(doc.content);toast('Texte copié.');break;}case 'import':{el.disabled=true;el.innerHTML='<span class="spinner"></span> Import en cours…';const result=await post('/import-snapshot');toast(`${number(result.imported)} offres importées · ${number(result.skipped)} déjà présentes.`);await render();break;}case 'logout':sessionStorage.removeItem('jobapply-token');toast('Clé retirée de cet onglet.');render();break;}}catch(e){toast(e.message,true);el.disabled=false;if(action==='import')el.innerHTML=`${icon('download')}Réessayer l’import`;}});
document.addEventListener('input',event=>{if(event.target.id==='list-search'){clearTimeout(requestTimer);state.q=event.target.value;state.pagination=1;requestTimer=setTimeout(()=>render({preserveFocus:true}),280);}});
document.addEventListener('change',async event=>{const el=event.target;if(['source-filter','status-filter','signal-filter','profile-category'].includes(el.id)){state[el.id==='source-filter'?'source':el.id==='status-filter'?'status':el.id==='signal-filter'?'signal':'profileCategory']=el.value;state.pagination=1;render({preserveFocus:true});}if(el.id==='application-status'){el.disabled=true;try{await api(`/applications/${el.dataset.id}`,{method:'PATCH',body:JSON.stringify({status:el.value})});toast('Statut mis à jour.');await detail('application',el.dataset.id,true);render({preserveFocus:true});}catch(e){toast(e.message,true);el.disabled=false;}}});
document.addEventListener('submit',async event=>{const form=event.target;if(!['create-form','access-form'].includes(form.id))return;event.preventDefault();const submit=$('[type="submit"]',form);submit.disabled=true;try{if(form.id==='access-form'){sessionStorage.setItem('jobapply-token',new FormData(form).get('token').trim());await api('/settings');toast('Accès enregistré.');render();}else{const data=Object.fromEntries(new FormData(form));for(const key of ['company','job_title','source_url'])if(!data[key]?.trim())data[key]=null;const row=await post('/applications',data);$('#modal').close();toast('Votre dossier de candidature est créé.');await detail('application',row.id);render({preserveFocus:true});}}catch(e){if(form.id==='create-form')$('#create-error').textContent=e.message;else toast(e.message,true);}finally{submit.disabled=false;}});
$('#drawer-backdrop').addEventListener('click',closeDrawer);
$('#menu-button').addEventListener('click',()=>{const open=$('#sidebar').classList.toggle('open');$('#menu-button').setAttribute('aria-expanded',String(open));});
$('#profile-shortcut').addEventListener('click',()=>location.hash='profile');
function focusSearch(){if(['offers','applications','documents','companies'].includes(state.page)){$('#list-search')?.focus();return;}location.hash='offers';const start=Date.now();const wait=setInterval(()=>{if($('#list-search')||Date.now()-start>5000){clearInterval(wait);$('#list-search')?.focus();}},100);}
$('#global-search').addEventListener('click',focusSearch);
document.addEventListener('keydown',event=>{if(event.key==='Escape'){if(!$('#drawer').hidden)closeDrawer();$('#sidebar').classList.remove('open');$('#menu-button').setAttribute('aria-expanded','false');}if(event.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)){event.preventDefault();focusSearch();}if(event.key==='Tab'&&!$('#drawer').hidden){const focusable=Array.from($('#drawer').querySelectorAll('a[href],button:not([disabled]),input:not([disabled]),textarea:not([disabled]),select,iframe,[tabindex="0"]'));const first=focusable[0],last=focusable.at(-1);if(event.shiftKey&&(document.activeElement===first||document.activeElement===$('#drawer'))){event.preventDefault();last?.focus();}else if(!event.shiftKey&&(document.activeElement===last||document.activeElement===$('#drawer'))){event.preventDefault();first?.focus();}}});
$('#navigation').innerHTML=nav.map(([page,i,label])=>`<a href="#${page}" data-nav="${page}" class="nav-link">${icon(i)}<span>${label}</span>${['offers','applications'].includes(page)?'<span class="nav-count">—</span>':''}</a>`).join('');
$('#settings-link').innerHTML=`${icon('settings')}Réglages & connexions`;
$('#search-icon').innerHTML=icon('search');$('#today').textContent=new Intl.DateTimeFormat('fr-FR',{weekday:'short',day:'numeric',month:'short'}).format(new Date());
window.addEventListener('hashchange',navigate);navigate();
